"use client";

import { useEffect, useRef, useState } from "react";
import {
  ArrowUpRight,
  Building2,
  KeyRound,
  RefreshCw,
  ShieldCheck,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { integrationErrorMessage } from "@/hooks/use-integration-operation";
import { Alert } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  IntegrationError,
  type IntegrationConnection,
  type IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import type {
  EnterpriseConnectionAction,
  EnterpriseConnectionBinding,
} from "@/lib/integrations/enterprise";
import { isTrustedIntegrationAuthorizationUrl } from "@/lib/integrations/http-adapter";
import { withIntegrationCancellation } from "@/lib/integrations/cancelled-task";
import {
  acceptIntegrationConnectionResponse,
  integrationConnectionSnapshotMatches,
} from "@/lib/integrations/connection-snapshot";
import {
  ProductDate,
  ProductEmpty,
  ProductPanel,
  ProductStatus,
} from "./product-ui";

const actionLabels: Record<EnterpriseConnectionAction, [string, string]> = {
  "verify-domain": [
    "Check domain verification",
    "Comprobar verificación del dominio",
  ],
  "request-administrator-consent": [
    "Request administrator consent",
    "Solicitar consentimiento del administrador",
  ],
  "renew-subscription": [
    "Renew change subscription",
    "Renovar suscripción de cambios",
  ],
  synchronize: [
    "Start authorized synchronization",
    "Iniciar sincronización autorizada",
  ],
};

export function EnterpriseDiagnostics({
  binding,
  canManage,
  onConnectionChange,
  ...props
}: IntegrationWorkbenchProps & {
  binding?: EnterpriseConnectionBinding;
  canManage: boolean;
  onConnectionChange(connection: IntegrationConnection): void;
}) {
  const { l, locale } = useLanguage();
  const state = props.connection.enterprise;
  const [review, setReview] = useState<{
    action: EnterpriseConnectionAction;
    connection: IntegrationConnection;
  } | null>(null);
  const [acknowledged, setAcknowledged] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [authorization, setAuthorization] = useState<string | null>(null);
  const request = useRef<AbortController | null>(null);
  const currentConnection = useRef(props.connection);
  const retry = useRef<{ signature: string; key: string } | null>(null);
  const ready = props.connection.status === "connected";
  useEffect(() => {
    currentConnection.current = props.connection;
  }, [props.connection]);
  useEffect(() => {
    request.current?.abort();
    request.current = null;
    retry.current = null;
    setReview(null);
    setAcknowledged(false);
    setBusy(false);
    setError(null);
    setAuthorization(null);
    return () => request.current?.abort();
  }, [
    binding,
    props.adapter,
    props.scope.workspaceId,
    props.connection.id,
    props.connection.providerOptionId,
  ]);
  useEffect(() => {
    if (!ready || !canManage) {
      request.current?.abort();
      request.current = null;
      setReview(null);
      setAcknowledged(false);
      setAuthorization(null);
      setBusy(false);
      retry.current = null;
    }
  }, [ready, canManage]);
  async function perform() {
    if (
      !binding ||
      !review ||
      !acknowledged ||
      !canManage ||
      request.current ||
      !ready
    )
      return;
    if (
      !integrationConnectionSnapshotMatches(review.connection, props.connection)
    ) {
      setReview(null);
      setAcknowledged(false);
      setError(integrationErrorMessage("conflict", locale));
      return;
    }
    const controller = new AbortController();
    const scope = {
      workspaceId: props.scope.workspaceId,
      signal: controller.signal,
    };
    const cancel = () => controller.abort();
    props.scope.signal?.addEventListener("abort", cancel, { once: true });
    if (props.scope.signal?.aborted) controller.abort();
    request.current = controller;
    setBusy(true);
    setError(null);
    setAuthorization(null);
    const signature = `${scope.workspaceId}:${review.connection.id}:${review.connection.revision}:${review.action}`;
    if (retry.current?.signature !== signature)
      retry.current = { signature, key: crypto.randomUUID() };
    try {
      const result = await withIntegrationCancellation(
        () =>
          binding.perform({
            action: review.action,
            connection: structuredClone(review.connection),
            idempotencyKey: retry.current!.key,
            scope,
          }),
        scope,
      );
      if (!result || !["connected", "authorization"].includes(result.kind))
        throw new IntegrationError("provider-error");
      const connection = acceptIntegrationConnectionResponse(
        result.connection,
        currentConnection.current,
        props.definition,
        scope,
      );
      if (
        !integrationConnectionSnapshotMatches(
          review.connection,
          currentConnection.current,
        )
      )
        throw new IntegrationError("conflict");
      if (
        result.kind === "authorization" &&
        !isTrustedIntegrationAuthorizationUrl(
          result.url,
          props.adapter.authorizationOrigins,
        )
      )
        throw new IntegrationError("provider-error");
      if (controller.signal.aborted) return;
      onConnectionChange(connection);
      setReview(null);
      setAcknowledged(false);
      retry.current = null;
      if (result.kind === "authorization") setAuthorization(result.url);
    } catch (cause) {
      if (!controller.signal.aborted)
        setError(
          integrationErrorMessage(
            cause instanceof IntegrationError ? cause.code : "provider-error",
            locale,
          ),
        );
    } finally {
      props.scope.signal?.removeEventListener("abort", cancel);
      if (request.current === controller) {
        request.current = null;
        setBusy(false);
      }
    }
  }
  const unknown = (
    <ProductEmpty>
      {l(
        "Not reported by the connection backend.",
        "El backend de la conexión no ha informado este estado.",
      )}
    </ProductEmpty>
  );
  return (
    <div className="grid min-w-0 grid-cols-1 gap-5" data-enterprise-diagnostics>
      <div className="grid min-w-0 gap-5 xl:grid-cols-3">
        <ProductPanel
          title={
            <span className="flex items-center gap-2">
              <Building2 aria-hidden className="size-4 text-primary" />
              {l(
                "Domain and single sign-on",
                "Dominio e inicio de sesión único",
              )}
            </span>
          }
        >
          {state?.domain ? (
            <div className="space-y-4 text-xs">
              <p className="font-medium wrap-break-word">{state.domain.name}</p>
              <dl className="grid gap-3">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <dt>{l("Domain verification", "Verificación de dominio")}</dt>
                  <dd>
                    <ProductStatus value={state.domain.status} />
                  </dd>
                </div>
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <dt>SSO</dt>
                  <dd>
                    <ProductStatus value={state.domain.sso} />
                  </dd>
                </div>
              </dl>
              {state.domain.verification && (
                <div className="space-y-2 rounded-xl border border-border bg-surface-subtle p-3">
                  <p className="font-medium">
                    {l(
                      "DNS record supplied by your backend",
                      "Registro DNS proporcionado por tu backend",
                    )}
                  </p>
                  <dl className="space-y-2">
                    {[
                      ["Type", state.domain.verification.type],
                      ["Name", state.domain.verification.name],
                      ["Value", state.domain.verification.value],
                    ].map(([label, value]) => (
                      <div key={label}>
                        <dt className="text-muted-foreground">{label}</dt>
                        <dd className="mt-1 select-all font-mono text-[11px] wrap-break-word">
                          {value}
                        </dd>
                      </div>
                    ))}
                  </dl>
                </div>
              )}
            </div>
          ) : (
            unknown
          )}
          {state?.administratorApproval && (
            <div className="mt-5 border-t border-border pt-4 text-xs">
              <p className="mb-2 text-muted-foreground">
                {l(
                  "Organization administrator approval",
                  "Aprobación del administrador de la organización",
                )}
              </p>
              <ProductStatus value={state.administratorApproval.status} />
              {state.administratorApproval.reviewedBy && (
                <p className="mt-2 wrap-break-word">
                  {state.administratorApproval.reviewedBy}
                </p>
              )}
            </div>
          )}
        </ProductPanel>
        <ProductPanel
          title={
            <span className="flex items-center gap-2">
              <KeyRound aria-hidden className="size-4 text-primary" />
              {l("Provider consent", "Consentimiento del proveedor")}
            </span>
          }
        >
          {state?.permissionMode || state?.consent || state?.providerScopes ? (
            <div className="space-y-4 text-xs">
              {state.permissionMode && (
                <p>
                  {l("Permission mode", "Modo de permisos")}:{" "}
                  <Badge variant="outline">
                    {state.permissionMode === "application"
                      ? l("Application", "Aplicación")
                      : l("Delegated", "Delegado")}
                  </Badge>
                </p>
              )}
              {state.consent && (
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <span>
                    {l("Administrator consent", "Consentimiento administrador")}
                  </span>
                  <ProductStatus value={state.consent.status} />
                </div>
              )}
              {state.providerScopes && (
                <div>
                  <p className="mb-2 text-muted-foreground">
                    {l("Actual provider scopes", "Scopes reales del proveedor")}
                  </p>
                  {state.providerScopes.length ? (
                    <ul className="flex flex-wrap gap-2">
                      {state.providerScopes.map((name) => (
                        <li
                          key={name}
                          className="max-w-full rounded-lg border border-border bg-surface-subtle px-2 py-1 font-mono text-[10px] wrap-break-word"
                        >
                          {name}
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <p>
                      {l("No scopes reported.", "No se han informado scopes.")}
                    </p>
                  )}
                </div>
              )}
              <p className="leading-6 text-muted-foreground">
                {l(
                  "Logical UI grants are displayed separately in Connection. They do not establish provider consent.",
                  "Los permisos lógicos de UI se muestran por separado en Conexión. No establecen el consentimiento del proveedor.",
                )}
              </p>
            </div>
          ) : (
            unknown
          )}
        </ProductPanel>
        <ProductPanel
          title={
            <span className="flex items-center gap-2">
              <ShieldCheck aria-hidden className="size-4 text-primary" />
              {l("Policy and synchronization", "Política y sincronización")}
            </span>
          }
        >
          {state?.policy || state?.synchronization || state?.renewal ? (
            <div className="space-y-4 text-xs">
              {state.policy && (
                <div>
                  <p className="mb-2 font-medium">{state.policy.name}</p>
                  <ProductStatus value={state.policy.status} />
                  <ul className="mt-3 space-y-3">
                    {state.policy.checks.map((check) => (
                      <li
                        key={check.id}
                        className="flex flex-wrap items-center justify-between gap-2"
                      >
                        <span className="min-w-0 wrap-break-word">
                          {check.name}
                        </span>
                        <ProductStatus value={check.status} />
                      </li>
                    ))}
                  </ul>
                </div>
              )}
              {state.synchronization && (
                <div className="space-y-2 border-t border-border pt-3">
                  <p className="font-medium">
                    {l("Synchronization", "Sincronización")} ·{" "}
                    {state.synchronization.mode}
                  </p>
                  <ProductStatus value={state.synchronization.status} />
                  {state.synchronization.lastSuccessAt && (
                    <p>
                      <ProductDate
                        value={state.synchronization.lastSuccessAt}
                      />
                    </p>
                  )}
                  {state.synchronization.checkpointPresent !== undefined && (
                    <p className="text-muted-foreground">
                      {state.synchronization.checkpointPresent
                        ? l(
                            "Server checkpoint is present.",
                            "Existe un checkpoint del servidor.",
                          )
                        : l(
                            "No server checkpoint reported.",
                            "No se informa un checkpoint del servidor.",
                          )}
                    </p>
                  )}
                </div>
              )}
              {state.renewal && (
                <div className="space-y-2 border-t border-border pt-3">
                  <p className="font-medium">
                    {l(
                      "Change-notification renewal",
                      "Renovación de notificaciones de cambios",
                    )}
                  </p>
                  <ProductStatus value={state.renewal.status} />
                  {state.renewal.expiresAt && (
                    <p>
                      {l("Expires", "Caduca")}:{" "}
                      <ProductDate value={state.renewal.expiresAt} />
                    </p>
                  )}
                </div>
              )}
            </div>
          ) : (
            unknown
          )}
        </ProductPanel>
      </div>
      {props.adapter.mode === "demo" && (
        <p className="text-xs leading-6 text-muted-foreground">
          {l(
            "These are local policy fixtures. No domain, tenant or provider administrator has been contacted.",
            "Estos son ejemplos de política locales. No se ha contactado ningún dominio, tenant ni administrador del proveedor.",
          )}
        </p>
      )}
      {!canManage && (
        <p className="text-xs leading-6 text-muted-foreground">
          {l(
            "Your current role cannot change this connection's enterprise settings.",
            "Tu rol actual no puede cambiar la configuración empresarial de esta conexión.",
          )}
        </p>
      )}
      {binding?.actions.length ? (
        <div className="flex flex-wrap gap-2">
          {[...new Set(binding.actions)].map((action) => (
            <Button
              key={action}
              variant="outline"
              disabled={!ready || !canManage || busy}
              onClick={() => {
                setReview({
                  action,
                  connection: structuredClone(props.connection),
                });
                setAcknowledged(false);
                setError(null);
              }}
            >
              <RefreshCw aria-hidden />
              {l(...actionLabels[action])}
            </Button>
          ))}
        </div>
      ) : (
        <p className="text-xs leading-6 text-muted-foreground">
          {l(
            "Supply an enterprise binding to enable server-owned verification, consent, renewal and synchronization actions.",
            "Aporta un binding empresarial para activar verificación, consentimiento, renovación y sincronización gestionados por tu servidor.",
          )}
        </p>
      )}
      {error && <Alert variant="destructive" title={error} />}
      {authorization && (
        <Alert
          title={l(
            "Continue with the administrator",
            "Continuar con el administrador",
          )}
        >
          <a
            className="inline-flex min-h-11 items-center gap-2 text-xs font-medium underline"
            href={authorization}
            rel="noreferrer"
            target="_blank"
          >
            {l(
              "Open provider authorization",
              "Abrir autorización del proveedor",
            )}
            <ArrowUpRight aria-hidden className="size-4" />
          </a>
        </Alert>
      )}
      <Dialog
        open={!!review}
        onOpenChange={(open) => {
          if (!open && !busy) setReview(null);
        }}
      >
        <DialogContent>
          <DialogTitle>
            {review ? l(...actionLabels[review.action]) : ""}
          </DialogTitle>
          <DialogDescription>
            {l(
              "Your backend will authorize this request for the reviewed connection and workspace. Provider approval is reported only after it actually completes.",
              "Tu backend autorizará la solicitud para la conexión y el espacio revisados. La aprobación del proveedor se informa solo después de completarse.",
            )}
          </DialogDescription>
          {review && (
            <p className="text-xs">
              {review.connection.account.name} ·{" "}
              {review.connection.enterprise?.domain?.name ??
                review.connection.integrationId}
            </p>
          )}
          <label className="flex min-h-11 items-start gap-3 text-xs leading-6">
            <Checkbox
              checked={acknowledged}
              onCheckedChange={(value) => setAcknowledged(value === true)}
              disabled={busy}
            />
            {l(
              "I reviewed this connection and the requested action.",
              "He revisado esta conexión y la acción solicitada.",
            )}
          </label>
          <DialogFooter>
            {busy && (
              <Button variant="ghost" onClick={() => request.current?.abort()}>
                {l("Stop waiting", "Dejar de esperar")}
              </Button>
            )}
            <Button
              variant="outline"
              disabled={busy}
              onClick={() => setReview(null)}
            >
              {l("Cancel", "Cancelar")}
            </Button>
            <Button
              loading={busy}
              disabled={!acknowledged || busy || !ready || !canManage}
              onClick={() => void perform()}
            >
              {l("Continue", "Continuar")}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type {
  IntegrationAction,
  IntegrationDefinition,
  IntegrationField,
  IntegrationOperationKind,
  IntegrationRecord,
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "../../lib/integrations/contracts";
import type { DataTableQuery } from "../../lib/data-query";

export function findProductAction(
  definition: IntegrationDefinition,
  ...kinds: IntegrationOperationKind[]
) {
  for (const kind of kinds) {
    const action = definition.actions.find((item) => item.kind === kind);
    if (action) return action;
  }
  return undefined;
}

/** A configuration or permission change discards drafts tied to the old scope. */
export function productScopeKey({
  definition,
  connection,
  scope,
  adapter,
}: IntegrationWorkbenchProps) {
  return JSON.stringify([
    adapter.mode,
    definition.id,
    connection.id,
    connection.providerOptionId,
    connection.workspaceId,
    scope.workspaceId,
    connection.revision,
    connection.status,
    [...connection.resourceIds].sort(),
    [...connection.grantedPermissions].sort(),
  ]);
}

export function defaultActionValues(
  action?: IntegrationAction,
): IntegrationValues {
  return Object.fromEntries(
    (action?.fields ?? []).map((field) => [
      field.id,
      field.type === "toggle"
        ? false
        : field.type === "select"
          ? (field.options?.[0]?.value ?? "")
          : "",
    ]),
  );
}

/** A create recipe must never reuse the selected source record as its target. */
export function productRecordNeedsTarget(action?: IntegrationAction) {
  return (
    action?.kind === "update-record" ||
    (action?.kind === "save-record" &&
      action.fields.some(
        (field) => ["recordId", "id"].includes(field.id) && field.required,
      ))
  );
}

/** Demo reads can start immediately; consumer references remain explicit inputs. */
export function productReadDefaults(
  action: IntegrationAction | undefined,
  props: IntegrationWorkbenchProps,
): IntegrationValues {
  const values = defaultActionValues(action);
  if (props.adapter.mode !== "demo") return values;
  const start = new Date();
  start.setUTCHours(0, 0, 0, 0);
  const end = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
  for (const field of action?.fields ?? []) {
    if (!field.required || field.type !== "text") continue;
    if (field.id === "startAt") values[field.id] = start.toISOString();
    else if (field.id === "endAt") values[field.id] = end.toISOString();
    else if (/(?:Id|Ref)$/.test(field.id))
      values[field.id] = props.connection.resourceIds[0] ?? "";
  }
  return values;
}

const resourceFields = new Set([
  "resourceId",
  "resource",
  "sourceId",
  "collectionId",
  "tableId",
  "indexId",
  "channelId",
  "repositoryId",
  "projectId",
  "databaseId",
  "siteId",
]);

/** Explicit values win. A resource binding is always a consumer-authorized ID. */
export function productActionValues(
  action: IntegrationAction | undefined,
  values: IntegrationValues,
  resourceId = "",
): IntegrationValues {
  const output = { ...defaultActionValues(action), ...values };
  if (resourceId) {
    output.resourceId = resourceId;
    for (const field of action?.fields ?? []) {
      if (resourceFields.has(field.id) && !output[field.id]) {
        output[field.id] = resourceId;
      }
    }
  }
  return output;
}

export function invalidProductField(
  action: Pick<IntegrationAction, "fields"> | undefined,
  values: IntegrationValues,
): IntegrationField | undefined {
  return action?.fields.find((field) => {
    const value = values[field.id];
    const empty =
      value === undefined ||
      (typeof value === "string" && !value.trim()) ||
      (Array.isArray(value) && value.length === 0);
    if (empty) return field.required === true;
    if (field.type === "number") {
      return !Number.isFinite(
        typeof value === "number" ? value : Number(value),
      );
    }
    if (field.type === "toggle") return typeof value !== "boolean";
    if (field.type === "select") {
      return !field.options?.some((option) => option.value === value);
    }
    return false;
  });
}

export function parseProductArguments(
  source: string,
): { ok: true; json: string } | { ok: false } {
  function valid(value: unknown, depth = 0): boolean {
    if (depth > 20) return false;
    if (
      value === null ||
      typeof value === "string" ||
      typeof value === "boolean"
    )
      return true;
    if (typeof value === "number") return Number.isFinite(value);
    if (Array.isArray(value))
      return value.every((item) => valid(item, depth + 1));
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).every(
      ([key, item]) =>
        !["__proto__", "constructor", "prototype"].includes(key) &&
        valid(item, depth + 1),
    );
  }
  try {
    const value = JSON.parse(source);
    if (
      !value ||
      typeof value !== "object" ||
      Array.isArray(value) ||
      !valid(value)
    )
      return { ok: false };
    return { ok: true, json: JSON.stringify(value) };
  } catch {
    return { ok: false };
  }
}

/** The backend applies filters/sorting/page boundaries; the UI never re-pages results. */
export function productQueryValues(
  query: DataTableQuery,
  resourceId = "",
): IntegrationValues {
  const sort = query.sorting[0];
  const status = query.filters.find((filter) => filter.id === "status");
  const filterValue = status?.value;
  return {
    resourceId,
    query: query.search,
    search: query.search,
    filter: typeof filterValue === "string" ? filterValue : "",
    status: typeof filterValue === "string" ? filterValue : "",
    page: query.pagination.pageIndex,
    pageNumber: query.pagination.pageIndex + 1,
    pageIndex: query.pagination.pageIndex,
    pageSize: query.pagination.pageSize,
    limit: query.pagination.pageSize,
    offset: query.pagination.pageIndex * query.pagination.pageSize,
    sort: sort?.id ?? "",
    order: sort?.desc ? "desc" : "asc",
    direction: sort?.desc ? "desc" : "asc",
    filters: JSON.stringify(query.filters),
    sorting: JSON.stringify(query.sorting),
    queryState: JSON.stringify(query),
  };
}

export function mergeProductRecords(
  previous: readonly IntegrationRecord[],
  incoming: readonly IntegrationRecord[],
) {
  const records = new Map(previous.map((record) => [record.id, record]));
  for (const record of incoming) {
    if (!record.id) continue;
    const current = records.get(record.id);
    if (
      current &&
      Number.isFinite(Date.parse(current.updatedAt)) &&
      Number.isFinite(Date.parse(record.updatedAt)) &&
      Date.parse(record.updatedAt) < Date.parse(current.updatedAt)
    ) {
      continue;
    }
    records.set(record.id, record);
  }
  return [...records.values()];
}

export function optimisticProductRecord(
  record: IntegrationRecord,
  values: IntegrationValues,
  marker: string,
): IntegrationRecord {
  return {
    ...record,
    name: typeof values.name === "string" ? values.name : record.name,
    description:
      typeof values.description === "string"
        ? values.description
        : record.description,
    status: typeof values.status === "string" ? values.status : record.status,
    updatedAt: marker,
  };
}

/** Roll back only this mutation, never a newer query or another acknowledged write. */
export function rollbackProductRecord(
  records: readonly IntegrationRecord[],
  original: IntegrationRecord,
  marker: string,
) {
  return records.map((record) =>
    record.id === original.id && record.updatedAt === marker
      ? original
      : record,
  );
}

export function parseProductFields(
  source: string,
):
  | { ok: true; values: IntegrationValues }
  | { ok: false; reason: "json" | "values" } {
  let value: unknown;
  try {
    value = JSON.parse(source);
  } catch {
    return { ok: false, reason: "json" };
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, reason: "values" };
  }
  const entries = Object.entries(value);
  if (
    entries.some(
      ([key, item]) =>
        ["__proto__", "constructor", "prototype"].includes(key) ||
        !(
          typeof item === "string" ||
          typeof item === "boolean" ||
          (typeof item === "number" && Number.isFinite(item)) ||
          (Array.isArray(item) &&
            item.every((part) => typeof part === "string"))
        ),
    )
  ) {
    return { ok: false, reason: "values" };
  }
  return { ok: true, values: Object.fromEntries(entries) };
}

export function safeProductUrl(value?: string) {
  if (!value) return undefined;
  if (
    value.startsWith("/") &&
    !value.startsWith("//") &&
    !value.includes("\\")
  ) {
    return value;
  }
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) &&
      !url.username &&
      !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

export function productSearchSegments(text: string, query: string) {
  const term = query.trim();
  if (!term) return [{ text, match: false }];
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return text
    .split(new RegExp(`(${escaped})`, "ig"))
    .filter(Boolean)
    .map((part) => ({
      text: part,
      match: part.toLocaleLowerCase() === term.toLocaleLowerCase(),
    }));
}

export function productMapLocations(
  result: Extract<IntegrationResult, { kind: "map" }>,
) {
  const seen = new Set<string>();
  return result.locations.filter((location) => {
    if (
      !location.id ||
      seen.has(location.id) ||
      !Number.isFinite(location.latitude) ||
      !Number.isFinite(location.longitude) ||
      Math.abs(location.latitude) > 90 ||
      Math.abs(location.longitude) > 180
    ) {
      return false;
    }
    seen.add(location.id);
    return true;
  });
}

export type ProductFieldMapping = { source: string; target: string };
export function validProductMapping(mapping: readonly ProductFieldMapping[]) {
  const targets = new Set<string>();
  return (
    mapping.length > 0 &&
    mapping.every(({ source, target }) => {
      if (
        !source.trim() ||
        !target.trim() ||
        targets.has(target) ||
        ["__proto__", "constructor", "prototype"].includes(target)
      ) {
        return false;
      }
      targets.add(target);
      return true;
    })
  );
}

export function mapProductRecord(
  record: IntegrationRecord,
  mapping: readonly ProductFieldMapping[],
): IntegrationValues {
  const fields: IntegrationValues = {
    ...record.fields,
    id: record.id,
    name: record.name,
    title: record.name,
    status: record.status,
    description: record.description,
    type: record.type,
    updatedAt: record.updatedAt,
  };
  return Object.fromEntries(
    mapping
      .filter(
        ({ source, target }) =>
          source in fields &&
          !["__proto__", "constructor", "prototype"].includes(target),
      )
      .map(({ source, target }) => [target, fields[source]]),
  );
}

/** Only declarative primitive input fields are read; schema code is never evaluated. */
export function productToolFields(
  record?: IntegrationRecord,
): IntegrationField[] {
  const source = record?.fields?.inputSchema ?? record?.fields?.schema;
  if (typeof source !== "string" || source.length > 50_000) return [];
  try {
    const schema = JSON.parse(source);
    if (
      !schema ||
      typeof schema !== "object" ||
      !schema.properties ||
      typeof schema.properties !== "object"
    )
      return [];
    const required = new Set(
      Array.isArray(schema.required) ? schema.required : [],
    );
    return Object.entries(schema.properties)
      .filter(([id]) => !["__proto__", "constructor", "prototype"].includes(id))
      .flatMap(([id, value]) => {
        if (!value || typeof value !== "object") return [];
        const property = value as {
          title?: string;
          description?: string;
          type?: string;
          enum?: unknown[];
        };
        if (
          !["string", "number", "integer", "boolean"].includes(
            property.type ?? "",
          )
        )
          return [];
        const title = typeof property.title === "string" ? property.title : id;
        const options = Array.isArray(property.enum)
          ? property.enum
              .filter((item): item is string => typeof item === "string")
              .map((item) => ({ value: item, label: { en: item, es: item } }))
          : [];
        return [
          {
            id,
            label: { en: title, es: title },
            description:
              typeof property.description === "string"
                ? { en: property.description, es: property.description }
                : undefined,
            type: options.length
              ? "select"
              : property.type === "boolean"
                ? "toggle"
                : ["number", "integer"].includes(property.type ?? "")
                  ? "number"
                  : "text",
            options: options.length ? options : undefined,
            required: required.has(id),
          } satisfies IntegrationField,
        ];
      });
  } catch {
    return [];
  }
}

